#include "Monstey_NavSeamAlternate.hpp"
#include "Monstey_Core.hpp"
#include <cmath>
#include <cstring>
#include <iostream>
using namespace Monstey;
namespace {
using V=Monstey_NavSeamVector4;using M=Monstey_NavigationBoundaryMeshView;using J=Monstey_Json;
struct Mesh{Monstey_Bytes faces=Monstey_Bytes(16),edges=Monstey_Bytes(80),vertices=Monstey_Bytes(64);std::array<std::int32_t,1>fm{-1};std::array<std::int32_t,4>em{-1,-1,-1,-1};M View()const{M m{};m.faces=faces;m.edges=edges;m.vertices=vertices;m.face_map=fm;m.edge_map=em;m.transform={V{1,0,0,0},V{0,1,0,0},V{0,0,1,0},V{0,0,0,0}};return m;}};
Mesh Quad(const std::array<V,4>&p){Mesh m;Monstey_PutU16(m.faces,8,4);for(unsigned i=0;i<4;++i){Monstey_PutU32(m.edges,i*20,i);Monstey_PutU32(m.edges,i*20+4,(i+1)%4);Monstey_PutU32(m.edges,i*20+8,0xffffffff);Monstey_PutU32(m.edges,i*20+12,0xffffffff);std::memcpy(m.vertices.data()+i*16,p[i].data(),16);}return m;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned groups=0;auto a=Quad({V{0,0,0,3},V{2,0,0,7},V{2,0,-2,11},V{0,0,-2,13}}),b=Quad({V{2,0,0,17},V{0,0,0,19},V{0,0,2,23},V{2,0,2,29}});const auto av=a.View(),bv=b.View();auto normal=Monstey_NavSeamFaceNormal(av,0);Monstey_Require(std::abs(normal.normal[1]-1)<1e-6&&std::abs(normal.area[0]-4)<1e-6&&normal.normal[0]==0&&normal.normal[2]==0,"Native fan normal/area differs");++groups;for(unsigned i=1;i<4;++i)Monstey_Require(normal.area[i]==normal.area[0],"Area reduction not replicated");++groups;auto empty=a;Monstey_PutU16(empty.faces,8,0);Monstey_PutU32(empty.edges,4,0x7fffffff);const auto fallback=Monstey_NavSeamFaceNormal(empty.View(),0);Monstey_Require(fallback.normal==V{0,0,1,0}&&fallback.area==V{0,0,0,0},"Native empty fallback performed extra endpoint read");++groups;Monstey_PutU16(empty.faces,8,0xffff);Monstey_Require(Monstey_NavSeamFaceNormal(empty.View(),0).normal==V{0,0,1,0},"Negative signed face count did not preserve normal fallback");++groups;Monstey_NavSeamAlternateSettings s{.1f,.01f,.02f,.9f,.9f};auto Run=[&](const M&x,const M&y,const auto&settings,int expected){const auto got=Monstey_NavSeamAlternateMatch(x,y,0,0,0,0,settings);Monstey_Require(got.status==expected,std::string("Alternate mismatch group ")+std::to_string(groups)+" expected "+std::to_string(expected)+" got "+std::to_string(got.status));++groups;return got;};const auto valid=Run(av,bv,s,-1);Monstey_Require(valid.candidate.intervals==std::array<float,4>{0,1,0,1}&&valid.candidate.score<1e-10,"Alternate full intervals/score differ");auto shifted=bv;shifted.transform[3]=V{0,.2f,0,0};Run(av,shifted,s,2);shifted=bv;shifted.transform[3]=V{3,0,0,0};Run(av,shifted,s,3);shifted=bv;shifted.transform[3]=V{1,0,0,0};auto partial=s;partial.minimum_overlap=1.5f;Run(av,shifted,partial,4);auto reverse=Quad({V{2,0,0,0},V{0,0,0,0},V{0,0,-2,0},V{2,0,-2,0}});Run(av,reverse.View(),s,12);Run(av,av,s,13);auto negativeSlack=s;negativeSlack.plane_slack=-.1f;Run(av,bv,negativeSlack,7);for(unsigned i=1;i<=32;++i){auto ta=av,tb=bv;ta.transform[3]=V{static_cast<float>(i),-7,23,9};tb.transform[3]=ta.transform[3];Run(ta,tb,s,-1);}auto rotated=av;rotated.transform[0]=V{0,0,1,0};rotated.transform[2]=V{-1,0,0,0};const auto rotatedNormal=Monstey_NavSeamFaceNormal(rotated,0);Monstey_Require(std::abs(rotatedNormal.normal[1]-1)<1e-6&&std::abs(rotatedNormal.area[0]-4)<1e-6,"Rotated face normal/area differs");++groups;bool bad=false;try{(void)Monstey_NavSeamFaceNormal(av,99);}catch(const std::exception&){bad=true;}Monstey_Require(bad,"Invalid owned face accepted");++groups;Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"alternate_native_codes",J::array({-1,2,3,4,7,12,13})},{"uncovered_alternate_code",5},{"original_program_called",false},{"process_accessed",false},{"scope","3BF31C face normal/area and selected ABD350 NULL-callback geometry"}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" alternate face/edge-pair groups\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}